<script>
document.querySelectorAll('.js-company-asaas-copy').forEach(function(button){button.addEventListener('click',function(){var input=document.getElementById(button.dataset.target),status=button.closest('.asaas-webhook-copy').querySelector('[role="status"]');if(!input||button.disabled)return;if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(input.value).then(function(){status.textContent='Valor copiado.';}).catch(function(){input.focus();input.select();status.textContent='Selecione e copie o valor.';});}else{input.focus();input.select();status.textContent='Selecione e copie o valor.';}});});
document.querySelectorAll('.js-company-asaas-reveal').forEach(function(button){button.addEventListener('click',function(){var input=document.getElementById(button.getAttribute('aria-controls'));if(!input)return;var reveal=input.type==='password';input.type=reveal?'text':'password';button.setAttribute('aria-pressed',reveal?'true':'false');button.textContent=reveal?'Ocultar':'Revelar';});});
window.addEventListener('pagehide',function(){document.querySelectorAll('[data-asaas-secret]').forEach(function(input){input.value='';input.type='password';});});
</script>
